package com.example.appointment.adapter.in.rest;
import com.example.appointment.application.port.in.CreateAppointmentUseCase; import com.example.appointment.application.service.AppointmentApplicationService; import com.example.appointment.domain.Appointment; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.UUID;
@RestController @RequestMapping("/api/v1/appointments") public class AppointmentController { private final CreateAppointmentUseCase create; private final AppointmentApplicationService query; public AppointmentController(CreateAppointmentUseCase c,AppointmentApplicationService q){create=c;query=q;} @PostMapping public ResponseEntity<AppointmentResponse> create(@Valid @RequestBody CreateAppointmentRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(map(create.create(new CreateAppointmentUseCase.CreateAppointmentCommand(r.vehicleId,r.dealerId,r.dealerName,r.slotId,r.serviceType))));} @GetMapping("/{id}") public AppointmentResponse get(@PathVariable UUID id){return map(query.get(id));} record CreateAppointmentRequest(@NotBlank String vehicleId,@NotBlank String dealerId,@NotBlank String dealerName,@NotBlank String slotId,@NotBlank String serviceType){} static AppointmentResponse map(Appointment a){return new AppointmentResponse(a.appointmentId(),a.vehicleId(),a.dealerId(),a.dealerName(),a.slotId(),a.serviceType(),a.partnerRequestReference(),a.externalDmsReference(),a.status().name(),a.createdAt(),a.bookedAt(),a.completedAt());} record AppointmentResponse(UUID appointmentId,String vehicleId,String dealerId,String dealerName,String slotId,String serviceType,String partnerRequestReference,String externalDmsReference,String status,Instant createdAt,Instant bookedAt,Instant completedAt){} }
